import{buildMapping,extractFromFiles,hasLz4Magic}from"./extract.min.js";import{buildGeoPayload,buildGeoPostBody}from"./geo.min.js";import{buildReport}from"./report.min.js";import{buildStoryGraph}from"./beats.min.js";import{encodeSeed}from"./seed.min.js";import{generateKey,commitment}from"./crockford.min.js";export function scanSystems(files,{log=()=>{},mapping={}}={}){log("extracting discoveries...");const{systems,playerStates,errors,rejectedTs,undated}=extractFromFiles(files,mapping,log);if(!systems.length){throw new Error(errors.length?errors[0].error:"no systems extracted")}log(`  ${systems.length} unique dated systems`);if(undated.length){log(`  ${undated.length} systems excluded (no dated events)`)}let rejectedCount=0;for(const c of rejectedTs.values())rejectedCount+=c;if(rejectedCount){log(`  ${rejectedCount} invalid timestamps rejected (< NMS release)`)}if(errors.length){log(`  ${errors.length} files in error: ${errors.map(e=>e.file).join(", ")}`)}return{systems,playerStates,errors,rejectedTs,undated,rejectedCount}}export async function loadMappingIfNeeded(files,{log=()=>{},loadMappingJson}){if(files.some(f=>hasLz4Magic(f.bytes))){log("obfuscated save detected, loading deobfuscation mapping...");const mapping=buildMapping(await loadMappingJson());log(`  ${Object.keys(mapping).length} mapping keys loaded`);return mapping}log("plaintext JSON format save, no mapping needed");return{}}export async function buildGeoForOptIn({systems},{log=()=>{}}={}){log("Payload A (geography)...");const geo=buildGeoPayload(systems);log(`  ${geo.systems.length} systems, ${geo.blackhole_routes.length} blackhole routes`);const post=await buildGeoPostBody(geo);const postJson=JSON.stringify(post);log(`  POST body: encoding ${post.encoding}, ${postJson.length} bytes (readable JSON: ${JSON.stringify(geo).length})`);return{geo,post,postJson}}export function buildGraphFromSystems({systems,playerStates},{log=()=>{}}={}){log("facts (report)...");const report=buildReport(systems,playerStates);log(`  ${report.totals.events} events, ${report.totals.regions} regions, ${report.contributors.length} contributors`);log(report.birth.source==="save_field"?`  certified birth: ${report.birth.sysaddress} (galaxy ${report.birth.galaxy}, planet ${report.birth.planet_index})`:`  inferred birth (cradle): region ${report.birth.region} galaxy ${report.birth.galaxy}`);log(`  trajectory: ${report.trajectory.teleports.length} teleports, ${report.trajectory.bases.length} bases`);log("beats (Payload B, pre-review)...");const graph=buildStoryGraph(report);log(`  ${graph.beats.length} beats detected`);return{report,graph}}export async function finalizeSeed(beats,{mosaicPublic=false,log=()=>{}}={}){const destroyKey=generateKey();const seed=await encodeSeed(beats,{mosaicPublic,commitment:await commitment(destroyKey)});log(`  ${beats.length} beats, seed ${seed.slice(0,5)} ${seed.length} chars`);return{seed,destroyKey}}export async function runPipeline(files,{log=()=>{},loadMappingJson}){const mapping=await loadMappingIfNeeded(files,{log,loadMappingJson});const{systems,playerStates,errors,undated,rejectedCount}=scanSystems(files,{log,mapping});const{geo,post,postJson}=await buildGeoForOptIn({systems},{log});const{report,graph}=buildGraphFromSystems({systems,playerStates},{log});const{seed,destroyKey}=await finalizeSeed(graph.beats,{log});return{systems,playerStates,geo,post,postJson,report,graph,seed,destroyKey,stats:{rejected:rejectedCount,undated,errors}}}
